1	// Acceptance test for the change request:
2	//   "Let me mark an invoice as paid. Keep a record every time I do so I can check back later."
3	//
4	// On a project's detail page each invoice shows its payment status (invoice-status) and, while it is
5	// still unpaid, a control to mark it paid (invoice-pay-<id>). Marking an invoice paid flips its
6	// status to paid, survives a fresh load from the server, and — because the request wants a record
7	// kept EVERY time — appends exactly one audit record `INVOICE_PAID id=<id> amount=<amount>` per
8	// marking. Marking one invoice must not touch its siblings.
9	//
10	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
11	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients`
12	// honours { id, name, email }, `projects` honours { id, name, clientId } and `invoices` honours
13	// { id, amount, projectId, status }.
14	import { test, expect, type Page, type Locator } from '@playwright/test';
15	import { resetAndSeed } from '../support/seed';
16	import { auditLines } from '../support/audit';
17	
18	// A status cell is "paid" when it carries the word "paid" on its own — matched case-insensitively so
19	// the test binds to the MEANING, not one capitalisation ("Paid"/"PAID"/"paid ✓" all count). The
20	// word boundary keeps "Unpaid"/"UNPAID" from matching, so the same regex distinguishes the two
21	// states without pinning the exact unpaid wording.
22	const PAID = /\bpaid\b/i;
23	
24	const invoiceRows = (page: Page) => page.locator('[data-testid^="invoice-row-"]');
25	const statusOf = (page: Page, id: number): Locator =>
26	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-status');
27	
28	// The audit record for one marking. The amount may be written bare (100) or with scale (100.00), so
29	// accept an optional fractional part; everything else is matched exactly.
30	const paidRecord = (id: number, amount: number) =>
31	  new RegExp(`^INVOICE_PAID id=${id} amount=${amount}(\\.\\d+)?$`);
32	
33	const paidRecordsFor = (id: number, amount: number): string[] =>
34	  auditLines().filter((line) => paidRecord(id, amount).test(line));
35	
36	test.describe('Mark an invoice as paid', () => {
37	  test('marking an unpaid invoice flips its status to paid, persists, and records it once', async ({
38	    page,
39	  }) => {
40	    await resetAndSeed({
41	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
42	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
43	      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'UNPAID' }],
44	    });
45	
46	    await page.goto('/projects/1');
47	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
48	
49	    // The invoice starts out not paid, and offers a control to mark it paid.
50	    await expect(statusOf(page, 1)).not.toHaveText(PAID);
51	    const pay = page.getByTestId('invoice-pay-1');
52	    await expect(pay).toBeVisible();
53	
54	    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
55	    // marking (not the seeding) wrote it.
56	    expect(auditLines()).toEqual([]);
57	
58	    await pay.click();
59	
60	    // The status now reads paid.
61	    await expect(statusOf(page, 1)).toHaveText(PAID);
62	
63	    // And exactly one record was kept for this marking, carrying the invoice's id and amount.
64	    expect(paidRecordsFor(1, 100)).toHaveLength(1);
65	    expect(auditLines()).toHaveLength(1);
66	
67	    // The paid status is held by the server, not just the page: it survives a fresh load, and
68	    // reloading does not record the marking a second time.
69	    await page.reload();
70	    await expect(statusOf(page, 1)).toHaveText(PAID);
71	    expect(paidRecordsFor(1, 100)).toHaveLength(1);
72	    expect(auditLines()).toHaveLength(1);
73	  });
74	
75	  test('marking one invoice leaves the others untouched, and each marking keeps its own record', async ({
76	    page,
77	  }) => {
78	    await resetAndSeed({
79	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
80	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
81	      invoices: [
82	        { id: 1, amount: 100, projectId: 1, status: 'UNPAID' },
