104	    await page.getByTestId('invoice-pay-2').click();
105	    await expect(statusOf(page, 2)).toHaveText(PAID);
106	
107	    expect(paidRecordsFor(1, 100)).toHaveLength(1);
108	    expect(paidRecordsFor(2, 250)).toHaveLength(1);
109	    expect(auditLines()).toHaveLength(2);
110	  });
111	
