113	    await resetAndSeed({
114	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
115	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
116	      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'PAID' }],
117	    });
118	
