120	
121	    // The status reflects the persisted state: this invoice is already paid.
122	    await expect(statusOf(page, 1)).toHaveText(PAID);
123	
124	    // Merely loading a paid invoice records nothing — the record is kept when the marking happens,
125	    // not on every view.
