    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
    // marking (not the seeding) wrote it.
    expect(auditLines()).toEqual([]);

    await pay.click();

    // The status now reads paid.
    await expect(statusOf(page, 1)).toHaveText(PAID);

    // And exactly one record was kept for this marking, carrying the invoice's id and amount.
    expect(paidRecordsFor(1, 100)).toHaveLength(1);
    expect(auditLines()).toHaveLength(1);

    // The paid status is held by the server, not just the page: it survives a fresh load, and
    // reloading does not record the marking a second time.
    await page.reload();
    await expect(statusOf(page, 1)).toHaveText(PAID);
    expect(paidRecordsFor(1, 100)).toHaveLength(1);
    expect(auditLines()).toHaveLength(1);
  });

  test('marking one invoice leaves the others untouched, and each marking keeps its own record', async ({
    page,
  }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
      invoices: [
        { id: 1, amount: 100, projectId: 1, status: 'UNPAID' },
        { id: 2, amount: 250, projectId: 1, status: 'UNPAID' },
      ],
    });

    await page.goto('/projects/1');
    await expect(invoiceRows(page)).toHaveCount(2);
    await expect(statusOf(page, 1)).not.toHaveText(PAID);
    await expect(statusOf(page, 2)).not.toHaveText(PAID);

    // Mark the first invoice paid.
    await page.getByTestId('invoice-pay-1').click();

    // Only that invoice changed; its sibling is still unpaid.
    await expect(statusOf(page, 1)).toHaveText(PAID);
    await expect(statusOf(page, 2)).not.toHaveText(PAID);

    // Exactly one record so far, for the invoice that was marked.
    expect(paidRecordsFor(1, 100)).toHaveLength(1);
    expect(auditLines()).toHaveLength(1);

    // Mark the second invoice paid too — "every time I do" means a second record is kept.
    await page.getByTestId('invoice-pay-2').click();
    await expect(statusOf(page, 2)).toHaveText(PAID);

    expect(paidRecordsFor(1, 100)).toHaveLength(1);
    expect(paidRecordsFor(2, 250)).toHaveLength(1);
    expect(auditLines()).toHaveLength(2);
  });

  test('an invoice seeded as paid is shown as paid from the start', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'PAID' }],
    });

    await page.goto('/projects/1');

    // The status reflects the persisted state: this invoice is already paid.
    await expect(statusOf(page, 1)).toHaveText(PAID);

    // Merely loading a paid invoice records nothing — the record is kept when the marking happens,
    // not on every view.
    expect(auditLines()).toEqual([]);
  });
});

